// Lucide artwork is covered by components/icon/lucide.license.
export const SAMPLE_CHARTS_ICON =
  '<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 24 24" fill="none" stroke="#F077AF" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-shapes" aria-hidden="true"><path d="M8.3 10a.7.7 0 0 1-.626-1.079L11.4 3a.7.7 0 0 1 1.198-.043L16.3 8.9a.7.7 0 0 1-.572 1.1Z"></path><rect x="3" y="14" width="7" height="7" rx="1"></rect><circle cx="17.5" cy="17.5" r="3.5"></circle></svg>';

export const WRITING_STYLE_ICON =
  '<svg xmlns="http://www.w3.org/2000/svg" width="72" height="72" viewBox="0 0 24 24" fill="none" stroke="#0D0D0D" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-pen-tool" aria-hidden="true"><rect width="24" height="24" rx="5" fill="white" stroke="none"/><path d="m18 13-.654-4.736a4 4 0 00-2.756-3.266l-9.163-2.9a2 2 0 00-2.017.493l-.82.819a2 2 0 00-.492 2.017l2.9 9.163a4 4 0 003.266 2.756L13 18"></path><path d="M18.648 12.352a1.205 1.205 0 011.704 0l1.296 1.296a1.205 1.205 0 010 1.704l-6.296 6.296a1.205 1.205 0 01-1.704 0l-1.296-1.296a1.205 1.205 0 010-1.704z"></path><path d="m3 3 6.586 6.586"></path><circle cx="11" cy="11" r="2"></circle></svg>';

import type { ComponentType, SVGProps } from "react";

import * as icons from "./known-app-icons";
import { SAMPLE_CHARTS_ICON, WRITING_STYLE_ICON } from "./known-app-images";

type IconComponent = ComponentType<SVGProps<SVGSVGElement>>;

/**
 * The static known-app icon registry. Names are
 * normalized (lowercase, non-alphanumerics to dashes), `connector-` is
 * stripped, and a `-mcp-server` suffix falls back to the base name.
 */
const registry = new Map<string, IconComponent>(
  Object.entries({
    figma: icons.FigmaIcon,
    "file-csv": icons.FileCsvIcon,
    "file-pdf": icons.FilePdfIcon,
    "file-presentation": icons.FilePresentationIcon,
    "file-spreadsheet": icons.FileSpreadsheetIcon,
    "file-word-document": icons.FileWordDocumentIcon,
    git: icons.GitIcon,
    github: icons.GithubIcon,
    gmail: icons.GmailIcon,
    "google-calendar": icons.GoogleCalendarIcon,
    "google-docs": icons.GoogleDocsIcon,
    "google-drive": icons.GoogleDriveIcon,
    "google-sheets": icons.GoogleSheetsIcon,
    "google-slides": icons.GoogleSlidesIcon,
    linear: icons.LinearIcon,
    notion: icons.NotionIcon,
    presentations: icons.PresentationsIcon,
    salesforce: icons.SalesforceIcon,
    sites: icons.SitesIcon,
    slack: icons.SlackIcon,
    wallet: icons.WalletIcon,
  })
);

const normalize = (name: string) =>
  name
    .trim()
    .toLowerCase()
    .split(/[^a-z0-9]+/gu)
    .filter((part) => part.length > 0)
    .join("-");

export const knownAppIcon = (name: string | null | undefined) => {
  if (name === null || name === undefined) {
    return null;
  }

  const normalized = normalize(name).replace(/^connector-/u, "");

  const icon =
    registry.get(normalized) ??
    registry.get(normalized.replace(/-mcp-server$/u, ""));

  return icon ?? null;
};

/** IconUrl entries: images rather than components. */
const imageRegistry = new Map<string, string>([
  [
    "visualize",
    `data:image/svg+xml;utf8,${encodeURIComponent(SAMPLE_CHARTS_ICON)}`,
  ],
  [
    "write-like-me",
    `data:image/svg+xml;utf8,${encodeURIComponent(WRITING_STYLE_ICON)}`,
  ],
]);

export const knownAppImage = (name: string | null | undefined) => {
  if (name === null || name === undefined) {
    return null;
  }

  const normalized = normalize(name).replace(/^connector-/u, "");

  return (
    imageRegistry.get(normalized) ??
    imageRegistry.get(normalized.replace(/-mcp-server$/u, "")) ??
    null
  );
};

"use client";

import { isNil, isPresent } from "@/lib/present";
import { cn } from "@/lib/utils";
import {
  cloneElement,
  useCallback,
  useState,
  useSyncExternalStore,
} from "react";
import type { ReactElement } from "react";

import { knownAppIcon, knownAppImage } from "./known-apps";

/*
 * The plugin logo follows the element's nearest theme scope, so a dark panel
 * in a light page shows the dark logo. Remote URLs and fallback artwork are
 * chosen separately from the known-app icon registry.
 */

const COLOR_SCHEME_ATTRIBUTES = ["class", "data-theme", "style"];

const listeners = new Set<() => void>();
let observer: MutationObserver | null = null;

const subscribeToSchemeChanges = (onChange: () => void) => {
  listeners.add(onChange);

  if (isNil(observer)) {
    observer = new MutationObserver(() => {
      for (const listener of listeners) {
        listener();
      }
    });
    observer.observe(document.documentElement, {
      attributeFilter: COLOR_SCHEME_ATTRIBUTES,
      attributes: true,
      subtree: true,
    });
  }

  return () => {
    listeners.delete(onChange);

    if (listeners.size === 0) {
      observer?.disconnect();
      observer = null;
    }
  };
};

/** True when the element's nearest theme scope is dark. */
const useIsDarkScope = () => {
  const [element, setElement] = useState<Element | null>(null);

  const isDark = useSyncExternalStore(
    subscribeToSchemeChanges,
    () =>
      isPresent(element) && getComputedStyle(element).colorScheme === "dark",
    () => false
  );

  return [isDark, setElement] as const;
};

// Trim; an empty URL is no URL; dark prefers the dark URL.
const trimmed = (url: string | null | undefined) => {
  const value = url?.trim();

  return isNil(value) || value.length === 0 ? null : value;
};

const chooseLogoUrl = ({
  isDark,
  logoDarkUrl,
  logoUrl,
}: {
  isDark: boolean;
  logoDarkUrl?: string | null;
  logoUrl?: string | null;
}) => {
  const light = trimmed(logoUrl);
  const dark = trimmed(logoDarkUrl);

  return isDark ? (dark ?? light) : (light ?? dark);
};

interface SettingsPluginLogoProps {
  alt?: string;
  className?: string;
  /** The known-app registry lookup, before a remote logo. */
  knownAppId?: string;
  connectorId?: string;
  /** Shown when there is no URL or the image fails to load. */
  fallback: ReactElement<{ className?: string }>;
  logoDarkUrl?: string | null;
  logoUrl?: string | null;
}

const SettingsPluginLogo = ({
  alt = "",
  className,
  connectorId,
  fallback,
  knownAppId,
  logoDarkUrl,
  logoUrl,
}: SettingsPluginLogoProps) => {
  const [isDark, scopeRef] = useIsDarkScope();
  const [failedSrc, setFailedSrc] = useState<string | null>(null);
  const src = chooseLogoUrl({ isDark, logoDarkUrl, logoUrl });
  const failed = isPresent(src) && failedSrc === src;

  const markFailed = useCallback(() => {
    setFailedSrc(src);
  }, [src]);

  // The caller's className reaches the fallback as well.
  // oxlint-disable-next-line react/no-clone-element -- the component clones the fallback element to add the rounded class.
  const fallbackElement = cloneElement(fallback, {
    className: cn("rounded-2xs", className, fallback.props.className),
  });

  // oxlint-disable-next-line react/static-components -- this is a registry lookup of an existing component, not a component created during render
  const KnownIcon = knownAppIcon(knownAppId ?? connectorId);
  const knownImage = knownAppImage(knownAppId ?? connectorId);

  return (
    <span className="contents" ref={scopeRef}>
      {(() => {
        if (KnownIcon) {
          // oxlint-disable-next-line react/static-components -- a registry lookup, not a component created during render
          return <KnownIcon className={className} />;
        }

        if (knownImage !== null) {
          return (
            // oxlint-disable-next-line next/no-img-element -- the registry's iconUrl image
            <img alt={alt} className={className} src={knownImage} />
          );
        }

        if (isNil(src) || failed) {
          return fallbackElement;
        }

        return (
          // oxlint-disable-next-line next/no-img-element -- the logo is a remote or app URL of unknown size, loaded as the img with an error fallback
          <img
            alt={alt}
            className={cn("rounded-2xs object-contain", className)}
            key={src}
            onError={markFailed}
            src={src}
          />
        );
      })()}
    </span>
  );
};

export { SettingsPluginLogo };

export type { SettingsPluginLogoProps };

"use client";

import { TitlebarLeftInsetContext } from "@/components/layout/titlebar-inset";
import { Button } from "@/components/ui/button";
import {
  Menu,
  MenuContextMenu,
  MenuItem,
  MenuMessage,
  MenuSectionLabel,
  MenuSeparator,
} from "@/components/ui/menu";
import { SplitView } from "@/components/ui/split-view";
import { AppShellTab, AppShellTabList } from "@/components/ui/tabs";
import { TooltipHint } from "@/components/ui/tooltip";
import { isPresent } from "@/lib/present";
import { Plus } from "lucide-react";
import { createContext, useContext, useId } from "react";
import type { KeyboardEvent, ReactNode, Ref } from "react";

type SettingsNavigationRequest = (navigate: () => void) => void;

const SettingsNavigationRequestContext =
  createContext<SettingsNavigationRequest | null>(null);

interface SettingsPanelAction {
  id: string;
  label: string;
  onSelect: () => void;
}

interface SettingsPanelLauncher {
  actions: readonly SettingsPanelAction[];
  emptyMessage: string;
  loading: boolean;
  loadingMessage: string;
  suggested: readonly SettingsPanelAction[];
  suggestedLabel: string;
}

interface SettingsRightPanel {
  activeTab: string | null;
  launcher: SettingsPanelLauncher;
  launcherMode: "direct" | "menu";
  newTabLabel: string;
  onActivate: (id: string) => void;
  onClose: (id: string) => void;
  onNewTab: () => void;
  onOpenChange: (open: boolean) => void;
  open: boolean;
  tabListLabel: string;
  tabs: readonly {
    closable?: boolean;
    content: ReactNode;
    id: string;
    title: string;
  }[];
}

const SettingsPanelMenu = ({
  launcher,
  label,
}: {
  launcher: SettingsPanelLauncher;
  label: string;
}) => (
  <Menu
    align="start"
    contentWidth="panel"
    triggerButton={
      <Button aria-label={label} color="ghost" size="toolbar" uniform>
        <Plus aria-hidden="true" />
      </Button>
    }
  >
    {launcher.actions.length === 0 &&
    launcher.suggested.length === 0 &&
    !launcher.loading ? (
      <MenuMessage compact>{launcher.emptyMessage}</MenuMessage>
    ) : null}
    {launcher.actions.map((action) => (
      <MenuItem
        key={action.id}
        onSelect={() => {
          action.onSelect();
        }}
      >
        {action.label}
      </MenuItem>
    ))}
    {launcher.loading ? (
      <MenuMessage compact>{launcher.loadingMessage}</MenuMessage>
    ) : null}
    {launcher.suggested.length > 0 ? (
      <>
        {launcher.actions.length > 0 ? <MenuSeparator /> : null}
        <MenuSectionLabel>{launcher.suggestedLabel}</MenuSectionLabel>
        {launcher.suggested.map((action) => (
          <MenuItem
            key={action.id}
            onSelect={() => {
              action.onSelect();
            }}
          >
            {action.label}
          </MenuItem>
        ))}
      </>
    ) : null}
  </Menu>
);

const SettingsPanelDirectLauncher = ({
  launcher,
  label,
  onOpen,
}: {
  launcher: SettingsPanelLauncher;
  label: string;
  onOpen: () => void;
}) => (
  <TooltipHint content={label} openDelay={250}>
    <MenuContextMenu
      disableNative
      contentWidth="panel"
      items={[
        ...launcher.actions.map((action) => ({
          id: action.id,
          message: { defaultMessage: action.label, id: action.id },
          onSelect: action.onSelect,
        })),
        ...(launcher.loading
          ? [
              {
                id: "loading",
                message: {
                  defaultMessage: launcher.loadingMessage,
                  id: "loading",
                },
                type: "label" as const,
              },
            ]
          : []),
        ...(launcher.suggested.length > 0
          ? [
              {
                id: "suggested",
                message: {
                  defaultMessage: launcher.suggestedLabel,
                  id: "suggested",
                },
                type: "label" as const,
              },
              ...launcher.suggested.map((action) => ({
                id: action.id,
                message: { defaultMessage: action.label, id: action.id },
                onSelect: action.onSelect,
              })),
            ]
          : []),
        ...(launcher.actions.length === 0 &&
        launcher.suggested.length === 0 &&
        !launcher.loading
          ? [
              {
                id: "empty",
                message: { defaultMessage: launcher.emptyMessage, id: "empty" },
                type: "label" as const,
              },
            ]
          : []),
      ]}
    >
      <Button
        aria-label={label}
        color="ghost"
        size="toolbar"
        uniform
        onClick={onOpen}
      >
        <Plus aria-hidden="true" />
      </Button>
    </MenuContextMenu>
  </TooltipHint>
);

interface SettingsPageFrameProps {
  children?: ReactNode;
  legacyContentRef?: Ref<HTMLDivElement>;
  requestNavigation?: SettingsNavigationRequest | null;
  rightPanel?: SettingsRightPanel;
  sidebar?: ReactNode;
  titlebarLeftInset?: number;
  workspaceKey?: string | null;
}

const SettingsPageFrame = ({
  children,
  legacyContentRef,
  requestNavigation,
  rightPanel,
  sidebar,
  titlebarLeftInset = 0,
  workspaceKey,
}: SettingsPageFrameProps) => {
  const inheritedRequest = useContext(SettingsNavigationRequestContext);
  const panelPrefix = useId();

  const handlePanelKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    const { target } = event;

    if (
      !(target instanceof HTMLButtonElement) ||
      target.getAttribute("role") !== "tab" ||
      !rightPanel
    ) {
      return;
    }

    const list = target.closest('[role="tablist"]');

    if (!list) {
      return;
    }

    const tabs = [
      ...list.querySelectorAll<HTMLButtonElement>(
        '[role="tab"]:not(:disabled)'
      ),
    ];

    const index = tabs.indexOf(target);

    if (event.key === "Delete") {
      const tab = rightPanel.tabs[index];

      if (tab?.closable === true) {
        rightPanel.onClose(tab.id);
        event.preventDefault();
        requestAnimationFrame(() => {
          const remaining = [
            ...list.querySelectorAll<HTMLButtonElement>(
              '[role="tab"]:not(:disabled)'
            ),
          ].filter((item) => !item.closest("[inert]"));

          (
            remaining.find(
              (item) => item.getAttribute("aria-selected") === "true"
            ) ?? remaining[0]
          )?.focus({ preventScroll: true });
        });
      }

      return;
    }

    if (
      event.defaultPrevented ||
      event.altKey ||
      event.ctrlKey ||
      event.metaKey ||
      event.shiftKey ||
      !["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)
    ) {
      return;
    }

    const rtl = getComputedStyle(list).direction === "rtl";
    let next: number;

    if (event.key === "Home") {
      next = 0;
    } else if (event.key === "End") {
      next = tabs.length - 1;
    } else {
      const forward = (event.key === "ArrowRight") !== rtl;
      next = (index + (forward ? 1 : -1) + tabs.length) % tabs.length;
    }

    const nextTab = tabs[next];

    if (nextTab !== undefined && nextTab !== target) {
      nextTab.focus();
      rightPanel.onActivate(rightPanel.tabs[next].id);
    }

    event.preventDefault();
  };

  const page = (
    <div
      className="relative isolate flex h-full min-h-0 min-w-0 flex-col overflow-visible"
      data-ui-navigation-page
      ref={legacyContentRef}
    >
      {children}
    </div>
  );

  return (
    <SettingsNavigationRequestContext.Provider
      value={requestNavigation ?? inheritedRequest}
    >
      <TitlebarLeftInsetContext.Provider value={titlebarLeftInset}>
        <div className="flex h-full min-h-0 min-w-0" data-ck-shell-frame>
          {sidebar}
          <main className="min-h-0 min-w-0 flex-1" data-ck-shell-main-surface>
            {workspaceKey === "/settings" && isPresent(rightPanel) ? (
              <SplitView
                id="settings-page-frame"
                isRightOpen={rightPanel.open}
                left={page}
                onRightOpenChange={(open) => {
                  rightPanel.onOpenChange(open);
                }}
                right={
                  <div className="flex h-full min-h-0 flex-col bg-panel">
                    <div className="flex border-b">
                      <AppShellTabList ariaLabel={rightPanel.tabListLabel}>
                        {rightPanel.tabs.map((tab) => (
                          <AppShellTab
                            isActive={rightPanel.activeTab === tab.id}
                            isClosable={tab.closable}
                            tabActivatorProps={{
                              "aria-controls": `${panelPrefix}-panel-${encodeURIComponent(tab.id)}`,
                              "aria-keyshortcuts":
                                tab.closable === true ? "Delete" : undefined,
                              id: `${panelPrefix}-tab-${encodeURIComponent(tab.id)}`,
                              onKeyDown: handlePanelKeyDown,
                              tabIndex:
                                rightPanel.activeTab === tab.id ? 0 : -1,
                            }}
                            key={tab.id}
                            onActivate={() => {
                              rightPanel.onActivate(tab.id);
                            }}
                            onClose={() => {
                              rightPanel.onClose(tab.id);
                            }}
                            title={tab.title}
                          />
                        ))}
                      </AppShellTabList>
                      {rightPanel.launcherMode === "menu" ? (
                        <SettingsPanelMenu
                          label={rightPanel.newTabLabel}
                          launcher={rightPanel.launcher}
                        />
                      ) : (
                        <SettingsPanelDirectLauncher
                          label={rightPanel.newTabLabel}
                          launcher={rightPanel.launcher}
                          onOpen={() => {
                            rightPanel.onNewTab();
                          }}
                        />
                      )}
                    </div>
                    {rightPanel.tabs.map((tab) => (
                      <div
                        aria-labelledby={`${panelPrefix}-tab-${encodeURIComponent(tab.id)}`}
                        className="min-h-0 flex-1 overflow-auto"
                        hidden={rightPanel.activeTab !== tab.id}
                        id={`${panelPrefix}-panel-${encodeURIComponent(tab.id)}`}
                        key={tab.id}
                        role="tabpanel"
                        tabIndex={-1}
                      >
                        {tab.content}
                      </div>
                    ))}
                  </div>
                }
              />
            ) : (
              page
            )}
          </main>
        </div>
      </TitlebarLeftInsetContext.Provider>
    </SettingsNavigationRequestContext.Provider>
  );
};

export { SettingsNavigationRequestContext, SettingsPageFrame };

export type {
  SettingsNavigationRequest,
  SettingsPageFrameProps,
  SettingsRightPanel,
};

"use client";

